  IEnumerator CabCases(){Check(m is PlowCabMatch&&m.cabExperience&&m.option==2,"separate Cab Chaos entry forces first person");var pads=new Gamepad[4];m.SetupScreen();for(int i=0;i<4;i++){pads[i]=InputSystem.AddDevice<Gamepad>();m.setup.players[i].source=BowlingSource.WholeController;m.setup.players[i].pad=pads[i];}m.setup.count=8;bool started=m.StartMatch();m.ValidateSources(out var reason);log.AppendLine("CAB_START started="+started+" devicesReady="+m.DevicesReady+" focused="+Application.isFocused+" background="+InputSystem.settings.backgroundBehavior+" reason="+reason);for(int i=0;i<4;i++)log.AppendLine("CAB_PAD "+i+" id="+pads[i].deviceId+" enabled="+pads[i].enabled+" added="+pads[i].added+" native="+pads[i].native+" source="+m.setup.players[i].source);Check(started,"four-controller cab match starts");if(!started)yield break;yield return new WaitForSecondsRealtime(4.5f);Check(m.cameras.Length==4,"four independent cab views");if(m.cameras.Length!=4)yield break;for(int i=0;i<4;i++){Check(m.cabExtras.gps[i].follow==m.trucks[i].transform&&m.cabExtras.gps[i].cameraMain==m.cameras[i],"GPS owner "+i);Check(m.cabExtras.gps[i].canvas.renderMode==RenderMode.WorldSpace,"real vendor world-space GPS "+i);}Check(FindObjectsByType<AudioListener>().Length==1,"one listener with four dashboard GPS displays");
