   InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return null;yield return null;float deadline=Time.realtimeSinceStartup+12;bool tap=false;while(n.JugActive&&Time.realtimeSinceStartup<deadline){bool cue=n.CueIsOpen(m.trucks[0].body.linearVelocity.magnitude>1);var state=new GamepadState().WithButton(GamepadButton.LeftShoulder);if(cue&&!tap)state=state.WithButton(GamepadButton.RightShoulder);InputSystem.QueueStateEvent(pads[0],state);tap=cue&&!tap;yield return null;}Check(n.SuccessfulJugs==successes+1&&n.Spills==spills,"injected timed Taxi jug three-cue success");
   InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(.2f);n.SetPressure(.55f);InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return new WaitForSecondsRealtime(.1f);InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(1);Check(n.Spills==spills+1&&n.CabMess,"early release genuinely spills owning jug");
